<?php
declare(strict_types=1);
namespace App\Application\QuestionLearning\Service;
use App\Application\QuestionLearning\AI\QuestionExplanationResponseValidator;use App\Application\QuestionLearning\Port\QuestionExplanationContextReaderInterface;use App\Application\QuestionLearning\Port\QuestionExplanationProviderInterface;use App\Domain\QuestionLearning\Repository\QuestionExplanationExecutionRepositoryInterface;
final readonly class ProcessNextQuestionExplanationService { public function __construct(private QuestionExplanationExecutionRepositoryInterface $executions,private QuestionExplanationContextReaderInterface $contexts,private QuestionExplanationProviderInterface $provider,private QuestionExplanationResponseValidator $validator) {} public function execute(\DateTimeImmutable $now):bool { $job=$this->executions->claimNextPending($now);if($job===null)return false;$execution=$this->executions->findById($job->executionId);if($execution===null)return false;try{$context=$this->contexts->read($execution);if($context===null)throw new \DomainException('Contexto autorizado indisponível.');$response=$this->provider->explain($context,$this->validator->jsonSchema());$execution->complete($this->validator->validate($response->payload,$execution->safetyMode),$response->provider,$response->model,$response->tokenCount,$response->durationMilliseconds,$now);$this->executions->save($execution);return true;}catch(\Throwable){$execution->fail('EXPLANATION_PROCESSING_FAILED','Não foi possível processar a explicação da questão.',$now);$this->executions->save($execution);return false;} } }
